  UNAUTHENTICATED: 401,
  MFA_REQUIRED: 403,
  ACCESS_CODE_REQUIRED: 401,
  FORBIDDEN: 403,
  SEGREGATION_OF_DUTIES: 403,
  NOT_FOUND: 404,
  CONFLICT: 409,
  OVERLAP: 409,
