  ALREADY_REVERSED: 409,
  ACCOUNT_HAS_ACTIVITY: 409,
  REFERENCED: 409,
  POSTED_JOURNAL_IMMUTABLE: 409,
  JOURNAL_LINES_IMMUTABLE: 409,
  PERIOD_LOCKED: 423,
  PERIODS_NOT_LOCKED: 423,
  STATEMENT_STALE: 409,
  STATEMENT_HAS_BLOCKING_EXCEPTIONS: 422,
  STATEMENT_RUN_IMMUTABLE: 409,
  STATEMENT_CONTENT_IMMUTABLE: 409,
